SELECT DISTINCT user_id
FROM requirement_pending_tasks
WHERE task_type = 'APPROVAL'
  AND requirement_id = #{requirementId}
  AND workflow_instance_id = #{workflowInstanceId}
  AND current_node_id = #{currentNodeId}
  AND user_id IS NOT NULL

mapper.insert:
INSERT INTO requirement_pending_tasks
(requirement_id, task_type, user_id, assignee_type, workflow_instance_id, current_node_id, current_node_name)

    SELECT #{task.requirementId}, 'CC_READ_ONLY', #{task.userId}, #{task.assigneeType},
           #{task.workflowInstanceId}, #{task.currentNodeId}, #{task.currentNodeName}
    FROM DUAL
    WHERE NOT EXISTS (
        SELECT 1
        FROM requirement_pending_tasks existing
        WHERE existing.requirement_id = #{task.requirementId}
          AND existing.task_type = 'CC_READ_ONLY'
          AND existing.user_id = #{task.userId}
          AND existing.workflow_instance_id = #{task.workflowInstanceId}
          AND existing.current_node_id = #{task.currentNodeId}
    )
